import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Flow y ritmo de combate sostenible","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/flow.md","filePath":"es/game-design/combat/flow.md"}'),n={name:"es/game-design/combat/flow.md"};function r(s,e,d,c,l,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="flow-and-sustainable-combat-rhythm" tabindex="-1">Flow y ritmo de combate sostenible <a class="header-anchor" href="#flow-and-sustainable-combat-rhythm" aria-label="Enlace permanente a &quot;Flow y ritmo de combate sostenible&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Los ejemplos numéricos son hipótesis de prototipo, no equilibrio definitivo. <strong>Implementación/disponibilidad:</strong> no establecida para estas mecánicas. <strong>Verificación:</strong> revisión documental, sin prototipo jugable. <strong>Revisión:</strong> 2026-10-09, Batch 05.</p><p><a href="/Syrolands-Public/es/guide/combat/flow.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a> · <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a></p><h2 id="proposed-modern-only-layer" tabindex="-1">Capa exclusiva de Modern con estado Propuesto <a class="header-anchor" href="#proposed-modern-only-layer" aria-label="Enlace permanente a &quot;Capa exclusiva de Modern con estado Propuesto&quot;">​</a></h2><p>Flow mide la separación temporal entre <strong>entradas válidas de ataque/acción</strong> consecutivas. Un ritmo razonablemente rápido y estable puede entrar en Flow; la consistencia importa más que la velocidad máxima. El encadenamiento instantáneo/casi instantáneo repetido debería incurrir en costes crecientes en lugar de convertirse en la producción óptima de daño.</p><p>Flow debe ser legible, fácil de entender y tolerante con el juego normal. Debería añadir profundidad temporal sin convertirse en un truco obligatorio de juego rítmico ni una barrera de accesibilidad. Ninguna ventana de milisegundos, cantidad de acumulaciones o bonificación es definitiva; Batch 06 aporta únicamente valores de prueba con estado Experimental.</p><table tabindex="0"><thead><tr><th>Posible beneficio al mantener el ritmo</th><th>Posible penalización por encadenar demasiado rápido</th></tr></thead><tbody><tr><td>Menor coste de stamina</td><td>Coste de stamina creciente</td></tr><tr><td>Eficiencia de recuperación</td><td>Mayor recuperación</td></tr><tr><td>Mejor precisión/consistencia</td><td>Menor precisión/consistencia</td></tr><tr><td>Menor penalización de manejo</td><td>Peor manejo</td></tr><tr><td>Transiciones más fluidas</td><td>Más anticipación/compromiso; pérdida/reinicio temporal de Flow</td></tr></tbody></table><p>Son candidatos, no un paquete de bonificaciones concedidas automáticamente. Los valores base compartidos de las acciones y un modo Legacy viable siguen siendo restricciones. Todo beneficio de Flow debe ser explícito, acotado y probado frente a costes de oportunidad; no es un multiplicador oculto de daño Modern.</p><h2 id="prototype-alternatives" tabindex="-1">Alternativas de prototipo <a class="header-anchor" href="#prototype-alternatives" aria-label="Enlace permanente a &quot;Alternativas de prototipo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modelo candidato de cadencia</th><th>Qué evaluar</th></tr></thead><tbody><tr><td>Ventanas fijas</td><td>Claridad, tolerancia e incentivos al spam veloz</td></tr><tr><td>Bandas específicas del arma</td><td>Ritmo lento/pesado frente a rápido/ligero sin forzar el mismo tempo</td></tr><tr><td>Ritmo adaptativo/personal</td><td>Facilidad de aprendizaje, abuso de calibración y medición estable</td></tr><tr><td>Seguimiento por clase de arma frente a clase de acción</td><td>Acciones mixtas, cambios y transiciones</td></tr></tbody></table><p>Batch 05 dejó abiertas estas alternativas. Solo para la primera prueba, <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html#flow-test">Batch 06</a> selecciona ritmo derivado de recuperación, tres estados y efectos numéricos acotados. Los demás modelos son alternativas inactivas. Probar ritmo sostenible, interrupciones y ráfagas de 2–3+ acciones bajo las mismas restricciones de stamina/recuperación. Las entradas inválidas/repetidas no deben contar como ritmo productivo; qué fases aceptadas cuentan exactamente, cómo se trata la latencia y cómo cambios/pausas reinician el estado sigue Sin resolver. Una puntuación de ritmo declarada por el cliente no puede autorizar beneficios de juego.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Ventanas de entrada/salida/mantenimiento; magnitud de beneficios/penalizaciones; mínimos de recuperación; escalada de stamina; reinicios por inactividad/interrupción; manejo de entradas inválidas; acciones mixtas; cambio de modos/armas; accesibilidad y reasignación; equidad ante latencia; macros/automatización; visibilidad de respuesta y si seguir clases de armas o acciones. No se implementa esquema de estado ni temporizador nuevo de combate.</p>',13)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
